const req = $input.item.json;
const body = req.body || req;
const rule = body?.rule || {};
const agent = body?.agent || {};
const data = body?.data || {};
const sysmon = data?.win?.eventdata || {};
const groups = Array.isArray(rule?.groups) ? rule.groups : [];
const level = Number.parseInt(rule?.level || '0', 10) || 0;
const mitre = rule?.mitre || {};
const src_ip = data?.srcip || data?.src_ip || body?.src_ip || sysmon?.sourceIp || sysmon?.ipAddress || null;
const dest_ip = data?.dstip || data?.dest_ip || body?.dest_ip || sysmon?.destinationIp || null;
const username = sysmon?.targetUserName || sysmon?.user || data?.dstuser || data?.srcuser || null;
const hostname = sysmon?.computer || agent?.name || null;
const process_name = sysmon?.image || sysmon?.originalFileName || null;
const parent_process = sysmon?.parentImage || null;
const command_line = sysmon?.commandLine || sysmon?.scriptBlockText || null;
const dns_query = sysmon?.queryName || null;
const file_hash = sysmon?.hashes || null;
const event_id = body?.id || body?.event_id || null;
const fallbackKey = [rule?.id || 'unknown', agent?.id || agent?.name || 'unknown', src_ip || '', dest_ip || '', username || '', process_name || '', dns_query || ''].join('|');
const dedup_key = event_id ? `event:${event_id}` : `alert:${fallbackKey}`;
return [{ json: {
  alert_id: event_id, raw_alert: JSON.stringify(body).substring(0,3000),
  rule_id: String(rule?.id || 'unknown'), rule_desc: rule?.description || 'No description', rule_level: level,
  rule_groups: groups, mitre_ids: mitre?.id || [], mitre_tactics: mitre?.tactic || [],
  agent_id: agent?.id || '000', agent_name: agent?.name || 'unknown', timestamp: body?.timestamp || new Date().toISOString(),
  full_log: String(body?.full_log || '').substring(0,1000), src_ip, dest_ip, username, hostname, process_name, parent_process,
  command_line: String(command_line || '').substring(0,500), dns_query, file_hash, dedup_key, received_at: Date.now()
} }];

const alert = $input.item.json;
if (!alert.dedup_key) throw new Error('Missing deterministic alert deduplication key');
return [{ json: { ...alert, redis_dedup_key: `soar:dedup:v2:${alert.dedup_key}` } }];

const a = $input.item.json;
const groups = Array.isArray(a.rule_groups) ? a.rule_groups : [];
const is = g => groups.includes(g);
const level = a.rule_level;
const ruleId = String(a.rule_id);
const safe = v => String(v ?? '').replace(/[^A-Za-z0-9_.:@-]/g,'_').substring(0,180);
const internal = ip => /^10\.10\./.test(String(ip||'')) || /^192\.168\./.test(String(ip||''));
let scenario='GENERIC', severity='medium', response_actions=[];
if (is('dcsync') || ruleId==='510050') { scenario='DCSYNC'; severity='critical'; response_actions=['disable_account','block_ip','isolate_host']; }
else if (is('credential_dump') || is('mimikatz') || is('ntds')) { scenario='CRED_DUMP'; severity='critical'; response_actions=['isolate_host','disable_account']; }
else if (is('defense_evasion') || is('log_clearing')) { scenario='DEFENSE_EVASION'; severity='critical'; response_actions=['isolate_host']; }
else if (is('misp') || is('threat_intel') || is('misp_ip_match')) { scenario='IOC_MATCH'; severity='high'; response_actions=['block_ip']; }
else if (is('suricata')) { scenario='IDS_ALERT'; severity=level>=12?'high':'medium'; response_actions=level>=12?['block_ip']:[]; }
else if (is('brute_force') || is('password_spray') || is('account_lockout') || is('authentication_failed') || is('behavior_based')) { scenario=is('behavior_based')&&internal(a.src_ip)?'BRUTE_FORCE_INTERNAL':'BRUTE_FORCE'; severity=internal(a.src_ip)?'critical':'high'; response_actions=internal(a.src_ip)?['isolate_source_host','disable_account','block_ip','investigate_source_compromise']:['disable_account','block_ip']; }
else if (is('lateral_movement') || is('psexec') || is('wmi') || is('winrm')) { scenario='LATERAL_MOVE'; severity='high'; response_actions=['isolate_host','block_ip']; }
else if (is('persistence') || is('registry_run') || is('scheduled_task')) { scenario='PERSISTENCE'; severity='medium'; }
else if (is('windows') && (ruleId.startsWith('510') || level>=12)) { scenario='WINDOWS_HIGH'; severity=level>=14?'critical':'high'; response_actions=level>=14?['isolate_host']:[]; }
else if (level>=12) { scenario='GENERIC_HIGH'; severity=level>=14?'critical':'high'; }
else if (level>=7) { scenario='GENERIC_MEDIUM'; severity='medium'; }
const agent=safe(a.agent_name), src=safe(a.src_ip), user=safe(a.username);
let splunk_query = `index=wazuh agent.name="${agent}" earliest=-30m | stats count by rule.id rule.description agent.name | sort -count`;
if (scenario.startsWith('BRUTE_FORCE')) splunk_query=`index=wazuh (data.win.eventdata.targetUserName="${user}" OR src_ip="${src}") earliest=-30m | stats count by rule.id rule.description src_ip data.win.eventdata.targetUserName agent.name | sort -count`;
else if (scenario==='IDS_ALERT') splunk_query=`index=wazuh src_ip="${src}" rule.groups=suricata earliest=-1h | stats count by rule.id rule.description dest_ip | sort -count`;
else if (scenario==='IOC_MATCH') { const ioc=safe(a.src_ip||a.dest_ip||a.dns_query); splunk_query=`index=wazuh (src_ip="${ioc}" OR dest_ip="${ioc}") earliest=-6h | stats count by rule.id rule.description agent.name | sort -count`; }
const hash = String(a.file_hash || '').trim().toLowerCase();
const domain = String(a.dns_query || '').trim().toLowerCase().replace(/\.$/, '');
const ip = String(a.src_ip || a.dest_ip || '').trim();
const validHash = /^(?:[a-f0-9]{32}|[a-f0-9]{40}|[a-f0-9]{64})$/.test(hash);
const validDomain = /^(?=.{1,253}$)(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/.test(domain);
const validIp = /^(?:(?:25[0-5]|2[0-4]\d|1?\d?\d)\.){3}(?:25[0-5]|2[0-4]\d|1?\d?\d)$/.test(ip);
const ioc_type = validHash ? 'hash' : validDomain ? 'domain' : validIp ? 'ip' : null;
const ioc_value = ioc_type === 'hash' ? hash : ioc_type === 'domain' ? domain : ioc_type === 'ip' ? ip : null;
return [{ json: { ...a, scenario, severity, response_actions, splunk_query, ioc_type, ioc_value, is_internal_source: internal(a.src_ip), needs_ai_triage: level>=7 } }];

const alert = $('Classify Scenario').item.json;
const splunkRaw = $('Splunk Context Query').item.json;
const mispRaw = $input.item.json;
const cleanErr = e => String(e?.message || e || '').substring(0,400);
const splunk_status = splunkRaw?.error ? 'error' : 'ok';
const misp_status = mispRaw?._misp_skipped ? 'skipped' : (mispRaw?.error ? 'error' : 'ok');
let splunk_context=[];
if (splunk_status==='ok') { try { const raw=typeof splunkRaw==='string'?splunkRaw:JSON.stringify(splunkRaw); for (const line of raw.split('\n').filter(Boolean)) { try { const p=JSON.parse(line); if (p.result) splunk_context.push(p.result); } catch {} } } catch {} }
let attrs=[];
if (misp_status==='ok') { try { attrs=mispRaw?.response?.Attribute || mispRaw?.Attribute || []; } catch {} }
const misp_hits=Array.isArray(attrs)?attrs.map(a=>({type:a.type,value:a.value,category:a.category,event:a.Event?.info||'unknown',threat_level:a.Event?.threat_level_id||'unknown'})):[];
const enrichment={
  splunk_status, splunk_error:splunk_status==='error'?cleanErr(splunkRaw.error):'', splunk_events_found:splunk_context.length,
  splunk_summary:splunk_context.slice(0,10).map(r=>({rule_id:r['rule.id'],rule_desc:r['rule.description'],count:r.count,agent:r['agent.name'],mitre:r['rule.mitre.id']})),
  misp_status, misp_error:misp_status==='error'?cleanErr(mispRaw.error):'', misp_hits_found:misp_hits.length,
  misp_matches:misp_hits.slice(0,5), misp_is_known_ioc:misp_hits.length>0,
  enrichment_degraded:splunk_status==='error'||misp_status==='error'
};
return [{ json: { ...alert, enrichment } }];

const d=$input.item.json;
const alertData={scenario:d.scenario,rule_id:d.rule_id,rule_desc:d.rule_desc,level:d.rule_level,agent:d.agent_name,src_ip:d.src_ip,dest_ip:d.dest_ip,username:d.username,process:d.process_name,parent_process:d.parent_process,command_line:d.command_line,dns_query:d.dns_query,file_hash:d.file_hash,mitre_ids:d.mitre_ids,full_log:d.full_log};
const systemPrompt='Return ONLY valid compact JSON with exactly: verdict, confidence, severity, summary, recommended_actions, needs_escalation, escalation_reason. Use confidence 0-100. summary and escalation_reason max 120 characters. recommended_actions max 2 items, each max 80 characters. Treat unavailable enrichment as unknown. Do not authorize actions.';
const body={model:'qwen3:14b',format:'json',think:false,keep_alive:'10m',messages:[{role:'system',content:systemPrompt},{role:'user',content:'ALERT:
'+JSON.stringify(alertData)+'
ENRICHMENT:
'+JSON.stringify(d.enrichment)+'
AVAILABLE ACTIONS:
'+JSON.stringify(d.response_actions)}],stream:false,options:{temperature:0.1,num_predict:250,num_ctx:8192}};
return [{json:{...d,_ollama_body:JSON.stringify(body)}}];

const alert=$('Build Ollama Request').item.json;
const resp=$input.item.json;
function extract(raw){ if(!raw)return null; try{return JSON.parse(raw)}catch{} const m=String(raw).match(/```(?:json)?\s*([\s\S]*?)```/); if(m){try{return JSON.parse(m[1].trim())}catch{}} const b=String(raw).match(/\{[\s\S]*\}/); if(b){try{return JSON.parse(b[0])}catch{}} return null; }
const aiError=resp?.error?String(resp.error?.message||resp.error).substring(0,400):'';
const content=resp?.message?.content||'';
const verdict=extract(content);
const ai=verdict||{verdict:'needs_investigation',confidence:40,severity:alert.severity,attack_type:alert.scenario,mitre_techniques:alert.mitre_ids||[],kill_chain_phase:'unknown',summary:aiError?'AI service failed':'AI parsing failed',false_positive_indicators:[],recommended_actions:['Manual review required'],ioc_to_block:[],accounts_to_disable:[],needs_escalation:true,escalation_reason:aiError||'AI parse failure'};
ai.attack_type=String(ai.attack_type||alert.scenario||'unknown'); ai.mitre_techniques=Array.isArray(ai.mitre_techniques)?ai.mitre_techniques:(alert.mitre_ids||[]); ai.kill_chain_phase=String(ai.kill_chain_phase||'unknown'); ai.false_positive_indicators=Array.isArray(ai.false_positive_indicators)?ai.false_positive_indicators:[]; ai.ioc_to_block=Array.isArray(ai.ioc_to_block)?ai.ioc_to_block:[]; ai.accounts_to_disable=Array.isArray(ai.accounts_to_disable)?ai.accounts_to_disable:[]; const confidence=Math.max(0,Math.min(100,Number(ai.confidence)||0));
const alertSeverity=String(alert.severity??'medium').trim().toLowerCase();
const fallbackSeverity=['critical','high','medium','low'].includes(alertSeverity)?alertSeverity:'medium';
const aiSeverity=String(ai.severity??'').trim().toLowerCase();
const normalizedSeverity=aiSeverity==='4'||aiSeverity==='critical'||aiSeverity==='crit'?'critical':aiSeverity==='3'||aiSeverity==='high'||aiSeverity==='severe'?'high':aiSeverity==='2'||aiSeverity==='medium'||aiSeverity==='moderate'?'medium':aiSeverity==='1'||aiSeverity==='0'||aiSeverity==='low'||aiSeverity==='informational'||aiSeverity==='info'?'low':fallbackSeverity;
ai.severity=normalizedSeverity;
const enrichmentOk=!alert.enrichment?.enrichment_degraded;
const auto_candidate=confidence>=90 && alert.enrichment?.misp_is_known_ioc===true && enrichmentOk;
const automation_tier=confidence>=70 && !!ai.needs_escalation?'approval_required':'manual_only';
return [{json:{...alert,ai_verdict:ai,ai_raw:String(content).substring(0,500),ai_parse_success:!!verdict&&!aiError,ai_service_error:aiError,automation_tier,auto_candidate,final_severity:normalizedSeverity,verdict_label:ai.verdict,confidence,attack_summary:ai.summary,recommended_actions:Array.isArray(ai.recommended_actions)?ai.recommended_actions:[],ioc_to_block:Array.isArray(ai.ioc_to_block)?ai.ioc_to_block:[],accounts_to_disable:Array.isArray(ai.accounts_to_disable)?ai.accounts_to_disable:[],needs_escalation:!!ai.needs_escalation,escalation_reason:String(ai.escalation_reason||'')}}];

const d=$input.item.json;
const sevMap={critical:4,high:3,medium:2,low:1};
const observables=[];
if(d.src_ip)observables.push({dataType:'ip',data:d.src_ip,tags:['src_ip'],message:'Source IP'});
if(d.dest_ip)observables.push({dataType:'ip',data:d.dest_ip,tags:['dest_ip'],message:'Destination IP'});
if(d.username)observables.push({dataType:'other',data:d.username,tags:['username'],message:'Target account'});
if(d.dns_query)observables.push({dataType:'domain',data:d.dns_query,tags:['dns'],message:'DNS query'});
observables.push({dataType:'other',data:d.agent_name,tags:['agent'],message:'Wazuh agent'});
const sourceRef=d.alert_id?`wazuh-${d.alert_id}`:`${d.dedup_key}-${d.timestamp}`.substring(0,240);
const actions=(d.recommended_actions||[]).map((a,i)=>`${i+1}. ${a}`).join('
')||'Manual review';
const hive={title:`[SOAR] ${d.scenario}: ${d.rule_desc}`,description:`## AI Triage: ${d.verdict_label} (${d.confidence}% confidence)

${d.attack_summary}

### Enrichment health
- Splunk: ${d.enrichment?.splunk_status}
- MISP: ${d.enrichment?.misp_status}
- MISP known IOC: ${d.enrichment?.misp_is_known_ioc?'YES':'No'}

### Recommended actions
${actions}

*AI: gemma4:e4b | Tier: ${d.automation_tier} | Auto-candidate: ${d.auto_candidate}*`,type:'external',source:'soar-ai-triage-v2',sourceRef,severity:sevMap[d.final_severity]||2,tlp:2,tags:['soar','ai-triage-v2',d.scenario,d.verdict_label],observables};
return [{json:{...d,_hive_body:JSON.stringify(hive)}}];

const d=$('Parse AI Verdict').item.json;
const hive=$input.item.json;
const hiveId=hive?._id||hive?.id||null;
const hiveUrl=hiveId?`http://10.10.1.6:9000/index.html#!/alert/${hiveId}/details`:null;
const sev=d.final_severity||'medium';
const isCritical=sev==='critical'||sev==='high';
const health=`Splunk: ${d.enrichment?.splunk_status} | MISP: ${d.enrichment?.misp_status}`;
const text=`${sev.toUpperCase()} ${d.scenario}: ${d.rule_desc} (${d.confidence}% confidence) — ${health}`;
const blocks=[{type:'header',text:{type:'plain_text',text:`SOAR ${sev.toUpperCase()}: ${d.scenario}`,emoji:true}},{type:'section',text:{type:'mrkdwn',text:`*${d.rule_desc}*\n${d.attack_summary}`}},{type:'section',fields:[{type:'mrkdwn',text:`*Agent:* ${d.agent_name}`},{type:'mrkdwn',text:`*Source IP:* ${d.src_ip||'N/A'}`},{type:'mrkdwn',text:`*Confidence:* ${d.confidence}%`},{type:'mrkdwn',text:`*Enrichment:* ${health}`}]}];
if(hiveUrl)blocks.push({type:'actions',elements:[{type:'button',text:{type:'plain_text',text:'View in TheHive'},url:hiveUrl,action_id:'view_thehive'}]});
const alertsPayload=JSON.stringify({channel:'C0SLACKCHANNEL',text,blocks});
const criticalPayload=isCritical?JSON.stringify({channel:'C0SLACKCHANNEL',text,blocks}):null;
return [{json:{...d,_hive_id:hiveId,_slack_alerts:alertsPayload,_slack_critical:criticalPayload,_is_critical:isCritical}}];

const alert=$('Parse AI Verdict').item.json;
const hive=$('TheHive Create Alert').item.json;
const slackAlerts=$('Slack Notify Alerts').item.json;
const critical=$('Build Slack Message').item.json._is_critical;
const slackCritical=critical?$input.item.json:null;
const hiveOk=!!(hive?._id||hive?.id);
const slackAlertsOk=slackAlerts?.ok===true;
const slackCriticalOk=!critical || slackCritical?.ok===true;
return [{json:{status:'completed',rule_id:alert.rule_id,rule_desc:alert.rule_desc,agent:alert.agent_name,scenario:alert.scenario,timestamp:alert.timestamp,verdict:alert.verdict_label,confidence:alert.confidence,severity:alert.final_severity,attack_summary:alert.attack_summary,automation_tier:alert.automation_tier,auto_candidate:alert.auto_candidate,enrichment:alert.enrichment,recommended_actions:alert.recommended_actions,needs_escalation:alert.needs_escalation,thehive_alert_created:hiveOk,thehive_alert_id:hive?._id||hive?.id||null,slack_alerts_notified:slackAlertsOk,slack_critical_required:critical,slack_critical_notified:slackCriticalOk,pipeline_degraded:!!alert.enrichment?.enrichment_degraded||!hiveOk||!slackAlertsOk||!slackCriticalOk,ai_parse_success:alert.ai_parse_success,pipeline_completed:new Date().toISOString()}}];

const d = $('Parse AI Verdict').item.json;
const hive = $('TheHive Create Alert').item.json;
const hiveId = hive?._id || hive?.id || 'unknown';

function isIPv4(value) {
  if (typeof value !== 'string') return false;
  const parts = value.split('.');
  return parts.length === 4 && parts.every((part) => /^\d{1,3}$/.test(part) && Number(part) >= 0 && Number(part) <= 255);
}

const allowBlockIp = d.enrichment?.misp_is_known_ioc === true
  && d.enrichment?.enrichment_degraded !== true
  && isIPv4(d.src_ip);

const action_policy = {
  allow_block_ip: allowBlockIp,
  allow_disable_account: false,
  allow_isolate_host: false,
};

const ctx = {
  alert_id: hiveId,
  rule_id: d.rule_id,
  scenario: d.scenario,
  confidence: d.confidence,
  tier: d.automation_tier,
  auto_candidate: d.auto_candidate,
  src_ip: d.src_ip || '',
  dest_ip: d.dest_ip || '',
  username: d.username || '',
  agent_name: d.agent_name || '',
  agent_id: d.agent_id || '',
  ioc_to_block: allowBlockIp ? d.src_ip : '',
  accounts_to_disable: '',
  action_policy,
  recommended_actions: (d.recommended_actions || []).join('|'),
};

const value = JSON.stringify(ctx).substring(0, 1900);
const policyText = allowBlockIp
  ? `*Allowed containment:* Firewall block for MISP-confirmed IOC \`${d.src_ip}\`.`
  : '*Allowed containment:* None. Manual investigation and response are required.';

const blocks = [
  { type: 'header', text: { type: 'plain_text', text: `ACTION REQUIRED: ${d.scenario}`, emoji: true } },
  { type: 'section', text: { type: 'mrkdwn', text: `*${d.rule_desc}*\n${d.attack_summary}\n\n*Confidence:* ${d.confidence}% | *Severity:* ${d.final_severity}\n${policyText}` } },
  { type: 'actions', block_id: 'soar_approval_actions_v2', elements: [
    { type: 'button', style: 'primary', text: { type: 'plain_text', text: 'Approve Allowed Actions' }, action_id: 'approve_all', value },
    { type: 'button', style: 'danger', text: { type: 'plain_text', text: 'Reject' }, action_id: 'reject', value },
    { type: 'button', text: { type: 'plain_text', text: 'Investigate First' }, action_id: 'investigate', value },
  ] },
];

return [{ json: { _approval_payload: JSON.stringify({ channel: 'C0SLACKCHANNEL', text: `Approval required: ${d.scenario} on ${d.agent_name}`, blocks }) } }];

const alert = $('Dedup Check').item.json;
const counter = Number(Object.values($input.first().json)[0]);
if (!Number.isInteger(counter) || counter < 1) throw new Error('Redis did not return a valid deduplication counter');
return [{ json: { ...alert, dedup_count: counter, is_duplicate: counter > 1 } }];

const alert = $('Classify Scenario').item.json;
const genericRaw = $('Splunk Context Query').item.json || {};
const reusable = $input.item.json || {};
const genericRows = Array.isArray(genericRaw.rows) ? genericRaw.rows : (genericRaw.result ? (Array.isArray(genericRaw.result) ? genericRaw.result : [genericRaw.result]) : []);
const genericStatus = genericRaw.error ? 'error' : 'ok';
const genericError = genericStatus === 'error' ? String(genericRaw.error?.message || genericRaw.error || '').slice(0, 400) : '';
const enrichment = { ...(reusable.enrichment || {}), generic_splunk_status: genericStatus, generic_splunk_error: genericError, generic_splunk_events_found: genericRows.length, generic_splunk_summary: genericRows.slice(0, 10) };
enrichment.enrichment_degraded = Boolean(enrichment.enrichment_degraded || genericStatus === 'error');
return [{ json: { ...alert, observable: reusable.observable || null, enrichment } }];
